    put(code, f"{en[0].upper()}{en[1:]} {'are' if plural else 'is'} busy or {'were' if plural else 'was'} interrupted by an earlier error; wait a moment and try again, or reload the document.", f"{de} {'sind' if plural else 'ist'} beschäftigt oder {'wurden' if plural else 'wurde'} durch einen früheren Fehler unterbrochen; warten Sie einen Moment und versuchen Sie es erneut, oder laden Sie das Dokument neu.")


